  let r;
  try {
    r = await herramienta(m.accessToken, nombre, { codigo_confirmacion: codigo });
  } catch (e) {
    r = { error: 'No pude completar la acción ahora. Inténtalo de nuevo en unos minutos.' };
  }
  if (r.error) {
