  }

  if (preparado) {
    salida.push(
      botones(telefono, respuesta, [
        [`confirmar|${preparado.tipo}|${preparado.codigo}`, 'Confirmar'],
        [`cancelar|${preparado.tipo}|${preparado.codigo}`, 'Cancelar'],
      ])
    );
  } else {
    salida.push(texto(telefono, respuesta));
  }
}
return salida;

